sp_widget.css:
/* ==== HEADER SECTION ==== */
.custom-header {
  width: 100%;
  background: linear-gradient(120deg, #1e3a8a, #2563eb, #1e40af);
  color: white;
  padding: 60px 40px;
  border-radius: 0 0 50px 50px;
  position: relative;
  overflow: hidden;
  box-shadow: 0 8px 25px rgba(0,0,0,0.15);
  animation: fadeIn 1s ease;
}

.header-content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
}

.header-text h1 {
  font-size: 3em;
  margin: 0;
  letter-spacing: 1px;
  animation: slideIn 1s ease forwards;
}

.header-text p {
  font-size: 1.3em;
  margin-top: 10px;
  color: #e0e7ff;
}

/* Decorative Animated Wave */
.wave {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 200%;
  height: 120px;
  background: rgba(255,255,255,0.15);
  border-radius: 100%;
  transform: translateX(-25%);
  animation: waveMove 6s linear infinite;
}

/* Header Shapes */
.shape {
  border-radius: 8px;
  position: relative;
  animation: float 3s ease-in-out infinite;
}

.shape1 {
  width: 40px; height: 60px;
  background-color: #9ca3af;
}
.shape2 {
  width: 50px; height: 80px;
  background-color: #6b7280;
  animation-delay: 0.5s;
}
.shape3 {
  width: 30px; height: 50px;
  background-color: #93c5fd;
  animation-delay: 1s;
}

/* Decorative Dots */
.shape::before {
  content: "";
  position: absolute;
  width: 10px; height: 10px;
  border-radius: 50%;
  top: -14px; left: 50%;
  transform: translateX(-50%);
  background-color: #38bdf8;
  animation: pulse 2s infinite ease-in-out;
}

/* ==== CARD SECTION ==== */
.cards-section {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 25px;
  padding: 60px 20px;
  background-color: #f8fafc;
}

.card {
  background: white;
  border-radius: 20px;
  padding: 30px;
  width: 300px;
  box-shadow: 0 8px 20px rgba(0,0,0,0.1);
  text-align: center;
  transition: transform 0.4s ease, box-shadow 0.4s ease;
  animation: fadeInUp 0.8s ease both;
}

.card:hover {
  transform: translateY(-10px);
  box-shadow: 0 12px 30px rgba(0,0,0,0.15);
}

.card-icon {
  font-size: 45px;
  margin-bottom: 15px;
  animation: popIn 1s ease;
}

.card h3 {
  font-size: 1.3em;
  margin: 12px 0;
  color: #1e3a8a;
}

.card p {
  font-size: 1em;
  color: #555;
  margin-bottom: 25px;
}

/* Buttons */
.card-btn {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 8px;
  background: linear-gradient(to right, #2563eb, #1e40af);
  color: white;
  text-decoration: none;
  font-weight: bold;
  transition: all 0.3s ease;
}

.card-btn:hover {
  background: linear-gradient(to right, #1e40af, #2563eb);
  transform: scale(1.05);
  box-shadow: 0 0 15px rgba(37,99,235,0.4);
}

.disabled-btn {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 8px;
  background-color: #e5e7eb;
  color: #777;
  font-weight: bold;
}

/* ==== ANIMATIONS ==== */
@keyframes float {
  0%,100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

@keyframes pulse {
  0%,100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.5); opacity: 0.6; }
}

@keyframes waveMove {
  0% { transform: translateX(0) translateY(0); }
  100% { transform: translateX(-50%) translateY(0); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideIn {
  from { opacity: 0; transform: translateX(-30px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes popIn {
  0% { transform: scale(0); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

/* ==== UTILITY ANIMATION CLASSES ==== */
.fade-in { animation: fadeIn 1.2s ease both; }
.fade-in-up { animation: fadeInUp 1.2s ease both; }
.slide-in-left { animation: slideIn 1.2s ease both; }
.float-up { animation: float 4s ease-in-out infinite; }

/* Responsive */
@media (max-width: 768px) {
  .header-content { flex-direction: column; text-align: center; }
  .cards-section { flex-direction: column; align-items: center; }
}

sp_widget.script:
(function() {
  var userEmail = gs.getUser().getEmail();
  gs.info("User Email: " + userEmail, "x_vuram_financia_0");

  // -------------------
  // INDIVIDUAL LOOKUP
  // -------------------
  var glideRecordIndividual = new GlideRecordSecure('x_vuram_financia_0_fcc_kyc_individual_details');
  glideRecordIndividual.addQuery('email', userEmail);
  glideRecordIndividual.query();

  if (glideRecordIndividual.next()) {
    var indSysId = glideRecordIndividual.getUniqueValue();
    var forename = glideRecordIndividual.getValue('forename_in_full');
    gs.info("Individual record found. Sys ID: " + indSysId + " | Forename: " + forename, "x_vuram_financia_0");
    data.individual = true;

    // Lookup case by individual reference
    var glideRecordCase = new GlideRecordSecure('x_vuram_financia_0_fcc_kyc_cases');
    glideRecordCase.addQuery('individual', indSysId);
    glideRecordCase.orderByDesc('sys_created_on'); // get latest case if multiple
    glideRecordCase.query();

    if (glideRecordCase.next()) {
      var custType = glideRecordCase.getValue('customer_type');
      gs.info("Case record found. Forename: " + forename + " | Customer Type: " + custType, "x_vuram_financia_0");

      if (custType == "customer" || custType == "individual") {
        data.show_customer = true;
        data.show_entity = false;
        gs.info("Set data.show_customer = true and data.show_entity = false", "x_vuram_financia_0");
      } else if (custType == "entity") {
        data.show_customer = false;
        data.show_entity = true;
        gs.info("Set data.show_customer = false and data.show_entity = true", "x_vuram_financia_0");
      }
    } else {
      gs.info("No case found for individual Sys ID: " + indSysId, "x_vuram_financia_0");
    }
  } else {
    gs.info("No Individual record found for email: " + userEmail, "x_vuram_financia_0");
    data.individual = false;
  }

  // -------------------
  // ENTITY LOOKUP
  // -------------------
  var glideRecordEntity = new GlideRecordSecure('x_vuram_financia_0_fcc_kyc_entity_details');
  glideRecordEntity.addQuery('email_id', userEmail);
  glideRecordEntity.query();

  if (glideRecordEntity.next()) {
    var entSysId = glideRecordEntity.getUniqueValue();
    var legalName = glideRecordEntity.getValue('legal_name');
    gs.info("Entity record found. Sys ID: " + entSysId + " | Legal Name: " + legalName, "x_vuram_financia_0");
    data.entity = true;

    // Lookup case by entity reference
    var glideRecordCaseEntity = new GlideRecordSecure('x_vuram_financia_0_fcc_kyc_cases');
    glideRecordCaseEntity.addQuery('entity', entSysId); // Correct reference for entity
    glideRecordCaseEntity.orderByDesc('sys_created_on'); // latest case
    glideRecordCaseEntity.query();

    if (glideRecordCaseEntity.next()) {
      var custTypeEnt = glideRecordCaseEntity.getValue('customer_type');
      gs.info("Case record found for entity. Legal Name: " + legalName + " | Customer Type: " + custTypeEnt, "x_vuram_financia_0");

      if (custTypeEnt == "entity") {
        data.show_customer = false;
        data.show_entity = true;
        gs.info("Set data.show_customer = false and data.show_entity = true", "x_vuram_financia_0");
      } else if (custTypeEnt == "customer" || custTypeEnt == "individual") {
        data.show_customer = true;
        data.show_entity = false;
        gs.info("Set data.show_customer = true and data.show_entity = false", "x_vuram_financia_0");
      }
    } else {
      gs.info("No case found for entity Sys ID: " + entSysId, "x_vuram_financia_0");
    }
  } else {
    gs.info("No Entity record found for email: " + userEmail, "x_vuram_financia_0");
    data.entity = false;
  }

  // Log final values of flags for debugging
  gs.info("FINAL → show_customer=" + data.show_customer + ", show_entity=" + data.show_entity, "x_vuram_financia_0");

})();
